// New matches start facing world +Z; respawns retain the last movement heading.
export function resetBotBillboardFacing(view){
 if(view.a.human)return;
 view.facing??={x:0,z:1};view.facing.x=0;view.facing.z=1;
}

// Presentation only: retain movement facing like the local player billboard.
export function updateBotBillboardFacing(view,yaw){
 if(view.a.human)return;
 const s=view.a.state;view.facing??={x:0,z:1};
 if(Math.hypot(s.vx,s.vz)>.01){view.facing.x=s.vx;view.facing.z=s.vz;}
 view.sprite.material.map=view.sprite.userData.maps[view.facing.x*Math.sin(yaw)+view.facing.z*Math.cos(yaw)>=0?0:1];
}

// Match the current, visible castle collision footprint. Ships and harbor piers
// stay separate escape destinations; the arena centre is not a castle target.
export function computeBattleBlastZones(world){
 return world.castles.map((castle,team)=>{
  const bounds=new T.Box3(),harbor=world.harbors?.[team]?.root;castle.updateWorldMatrix(true,true);
  for(const mesh of world.solids){let owned=false,excluded=false;for(let p=mesh;p;p=p.parent){if(p===harbor||!p.visible)excluded=true;if(p===castle)owned=true;}if(!owned||excluded||mesh.userData.terrainCliff||!mesh.geometry)continue;mesh.geometry.computeBoundingBox();if(mesh.geometry.boundingBox)bounds.union(mesh.geometry.boundingBox.clone().applyMatrix4(mesh.matrixWorld));}
  if(bounds.isEmpty()){const p=castle.getWorldPosition(new T.Vector3());return {team,x:p.x,z:p.z,radius:100};}
  const centre=bounds.getCenter(new T.Vector3()),size=bounds.getSize(new T.Vector3());return {team,x:centre.x,z:centre.z,radius:Math.hypot(size.x,size.z)/2+8};
 });
}

